const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const dir=__dirname+'/',hash=x=>crypto.createHash('sha256').update(x).digest('hex'),copy=x=>JSON.parse(JSON.stringify(x));
function engine(){const box=vm.createContext({});for(const script of [...fs.readFileSync(dir+'source.html','utf8').matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)].slice(0,2))vm.runInContext(script[1],box);return {E:box.Yiwu,C:box.YiwuComputer};}
function random(values){const state={...values};return {state,next:side=>()=>{state[side]=(Math.imul(state[side],1664525)+1013904223)>>>0;return state[side]/4294967296;}};}
function actionArgs(a){return a.type==='pass'?[]:a.type==='rest'?[a.id,a.card]:[a.id,a.x,a.y];}
function verifyChoice(E,C,s,cmd,rng){
  const [op,...args]=cmd;
  if(s.phase==='board'){const a=C.board(s,rng.next(s.turn),'practice');assert.equal(a.type,op);assert.deepEqual(actionArgs(a),args);}
  else if(s.phase==='duel'){const x=C.combat(s,E.get(s,s.duel.a).side,rng.next(E.get(s,s.duel.a).side),'practice');if(op==='retreat')assert.equal(x,op);else{assert.equal(op,'resolve');assert.equal(x,args[0]);assert.equal(C.combat(s,E.get(s,s.duel.d).side,rng.next(E.get(s,s.duel.d).side),'practice'),args[1]);}}
}
function play(task,plan){
  const start=plan.states[task.state],{E,C}=engine(),s=copy(start.state),rng=random(start.rng),commands=copy(start.prefix);let steps=0,forced=false;
  while(s.phase!=='ended'&&s.ply<2000&&steps++<14000){
    if(s.phase==='board'){
      let a=C.board(s,rng.next(s.turn),'practice');
      if(!forced&&task.action){a=task.action;forced=true;}const args=actionArgs(a);E[a.type](s,...args);commands.push([a.type,...args]);
    }else{
      assert.equal(s.phase,'duel');const a=E.get(s,s.duel.a),d=E.get(s,s.duel.d),x=C.combat(s,a.side,rng.next(a.side),'practice');
      if(x==='retreat'){E.retreat(s);commands.push(['retreat']);}
      else{const y=C.combat(s,d.side,rng.next(d.side),'practice');E.resolve(s,x,y);commands.push(['resolve',x,y]);}
    }
  }
  assert.equal(s.phase,'ended','资源上限不是和局');if(task.action)assert(forced);else{assert.deepEqual(commands,start.control.commands);assert.equal(hash(JSON.stringify(s)),start.control.terminalSHA256);}
  return {task:task.index,state:task.state,action:task.action||null,winner:s.winner,reason:s.reason,plies:s.ply,defendingSide:start.state.turn,defenderAvoidsLoss:s.winner!==E.OTHER[start.state.turn],commands,terminalSHA256:hash(JSON.stringify(s)),final:s};
}
module.exports={engine,random,actionArgs,verifyChoice,play,hash,copy};

