const tasks=plan.tasks.filter(t=>t.index%plan.workers===shard),file=dir+'shard'+shard+'.json';assert(!fs.existsSync(file),'请先核查原进程和已保存结果');const out={shard,runs:[],errors:[],completed:false},save=()=>fs.writeFileSync(file,JSON.stringify(out,null,2)+'\n');save();
